mapper.update:
UPDATE orders
SET status = #{to},
    updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = #{from}

UPDATE orders
SET status = #{to},
    updated_at = NOW()
WHERE id = #{id}
  AND merchant_id = #{merchantId}
  AND status = #{from}

UPDATE orders
SET status = #{to},
    received_at = #{receivedAt},
    updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = #{from}

UPDATE orders
SET status = #{to},
    updated_at = NOW()
WHERE id = #{id}
  AND status = #{from}
  AND created_at <= #{cutoff}

mapper.select:
SELECT id
FROM orders
WHERE status = #{status}
  AND created_at <= #{cutoff}
ORDER BY created_at ASC, id ASC
LIMIT #{limit}
